data.query:
query IntegrationStaging(
  $where: IntegrationStagingWhereInput
  $statusWhere: StagingTableStatusWhereInput
) {
  stagingTableStatus(
    where: $statusWhere
  ) {
    edges {
      node {
        id
      }
    }
  }

  integrationStaging(where: $where) {
    edges {
      node {
        id
        statusId
        attemptCount
        request
        metadata
        integrationConfigId
        attemptCount
        integrationConfig {
          id
          parameters
          requestHandlerDataFlowId
          integrationDataFlowId
          responseDataFlowId
          autoRetryResponses
          maxRetryAttemps
          integrationType {
            concurrencyLimit
            connectionId
            connection {
              name
            }
            integrationConfigurations {
              edges {
                node {
                  id
                }
              }
            }
          }
        }
      }
    }
  }
}

